Factory (lines 162-171):
```ts
export type ContactGroupScope = 'sys' | 'acc';
function contactGroupQuery(action: string, scope: ContactGroupScope): AccessQuery {
  return {
    action,
    resource: `${scope}.contact-group`,
    attrs: {},
    ignoreExpression: true,
