const comps = dv.pages('"30-Components"').where(p => p.type === "component");
const families = {};
function getFamily(slug) {
  const s = slug.replace(/^falcon-/, "");
  if (/table/.test(s)) return "table";
  if (/input|field|textarea|number/.test(s)) return "input";
  if (/upload/.test(s)) return "uploader";
  if (/picker|calendar|date/.test(s)) return "picker";
  if (/popup|dialog|confirm/.test(s)) return "dialog";
  if (/stepper|wizard/.test(s)) return "wizard";
  if (/tabs|accordion|paginator/.test(s)) return "navigation";
  if (/select|dropdown|combobox|multi-sel/.test(s)) return "select";
  if (/radio|checkbox|switch/.test(s)) return "toggle";
  if (/menu/.test(s)) return "menu";
  if (/drawer/.test(s)) return "drawer";
  if (/tree/.test(s)) return "tree";
  if (/avatar|badge|tag|icon/.test(s)) return "visual";
  if (/toast|notification|message|tooltip/.test(s)) return "feedback";
  if (/card|panel|empty-state|filter/.test(s)) return "container";
  if (/otp|password|email|phone|mobile/.test(s)) return "identity-input";
  return "misc";
}
for (const c of comps) {
  const slug = c["component-slug"] ?? c.file.name;
  const fam = getFamily(slug);
  if (!families[fam]) families[fam] = [];
  families[fam].push(c.file.link);
}
const rows = Object.entries(families).sort().map(([fam, members]) => [fam, members.length, members.slice(0, 3).join(", ") + (members.length > 3 ? ", …" : "")]);
dv.table(["Family", "Count", "Sample"], rows);
