Example context provider implementation flow:

```csharp
public sealed class MetaWhatsAppContextProvider : IMetaWhatsAppContextProvider
{
    private readonly IProvisioningClient _provisioningClient;
    private readonly IMemoryCache _cache;

    public async Task<MetaWhatsAppIntegrationContext> GetContextAsync(
        MetaWhatsAppContextRequest request,
        CancellationToken cancellationToken = default)
    {
        var cacheKey = $"meta-wa-context:{request.TenantId}:{request.AccountId}:{request.ChannelId}";

        if (_cache.TryGetValue(cacheKey, out MetaWhatsAppIntegrationContext cached))
        {
            return cached;
        }

        var context = await _provisioningClient.GetMetaWhatsAppContextAsync(
            request.TenantId,
            request.AccountId,
            request.ChannelId,
            cancellationToken);

        if (context.Status != "ACTIVE")
        {
            throw new FalconBusinessException("WHATSAPP_CHANNEL_NOT_ACTIVE");
        }

        if (!context.Capabilities.TemplateManagement)
        {
            throw new FalconBusinessException("TEMPLATE_MANAGEMENT_NOT

_ENABLED");
        }

        _cache.Set(cacheKey, context, TimeSpan.FromMinutes(5));
        return context;
    }
}
```

Example access token provider implementation flow:

```csharp
public sealed class MetaAccessTokenProvider : IMetaAccessTokenProvider
{
    private readonly ISecretResolver _secretResolver;

    public async Task<MetaAccessToken> GetAccessTokenAsync(
        MetaWhatsAppIntegrationContext context,
        MetaTokenPurpose purpose,
        CancellationToken cancellationToken = default)
    {
        var secret = await _secretResolver.ResolveAsync(
            new SecretResolutionRequest
            {
                CredentialRef = context.CredentialRef,
                Purpose = purpose.ToString()
            },
            cancellationToken);

        return new MetaAccessToken
        {
            Value = secret.AccessToken,
            ExpiresAt = secret.ExpiresAt,
