import { SDK_VERSION, FalconSDK } from '@falcon/sdk';

declare global {
  interface Window {
    FalconMicroApps?: { [key: string]: any };
  }
}

export interface MicroAppDescriptor {
  name: string;
  scope: string;
  url: string;
  sdkRange: string;  // e.g. ">=1.0.0 <2.0.0"
}

export function loadMicroAppScript(url: string, scope: string): Promise<any> {
  return new Promise((resolve, reject) => {
    if (window.FalconMicroApps?.[scope]) {
      return resolve(window.FalconMicroApps[scope]);
    }

    const script = document.createElement('script');
    script.type = 'module';
    script.src = url;
    script.onload = () => {
      const microApp = window.FalconMicroApps?.[scope];
      if (!microApp) {
        reject(new Error(`Micro-app '${scope}' did not register itself on window.FalconMicroApps`));
      } else {
        resolve(microApp);
      }
    };
    script.onerror = () => reject(new Error(`Failed to load micro-app script: ${url}`));

    document.body.appendChild(script);
  });
}

// naive semver check; you can wire in semver.js instead
export function isSdkCompatible(range: string, sdkVersion: string): boolean {
  // Minimal: only support "^major.minor.patch" style like ">=1.0.0 <2.0.0"
  if (range.includes('<2.0.0') && sdkVersion.startsWith('1.')) {
    return true;
  }
  // Extend with a real semver check in production
  return true;
}

export async function loadAndInitMicroApp(
  descriptor: MicroAppDescriptor,
  sdk: FalconSDK
): Promise<any> {
  if (!isSdkCompatible(descriptor.sdkRange, sdk.version)) {
    throw new Error(
      `Micro-app '${descriptor.name}' requires SDK ${descriptor.sdkRange}, but shell has ${sdk.version}`
    );
  }

  const remote = await loadMicroAppScript(descriptor.

url, descriptor.scope);

  if (remote.init) {
    await remote.init({ sdk });
  }

  return remote;
}

