```
import {
  Component,
  Input,
  ViewChild,
  ViewContainerRef,
  OnInit,
  inject
} from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { loadAndInitMicroApp, MicroAppDescriptor } from '@falcon/host-bridge';
import { FalconSDK } from '@falcon/sdk';

@Component({
  selector: 'falcon-microapp-outlet',
  template: `<ng-container #vc></ng-container>`,
  standalone: true,
})
export class MicroappOutletComponent implements OnInit {
  @Input() microAppName!: string;

  @ViewChild('vc', { read: ViewContainerRef, static: true })
  vc!: ViewContainerRef;

  private http = inject(HttpClient);
  private sdk = window.FalconSDK as FalconSDK;

  async ngOnInit() {
    try {
      const descriptor = await this.http
        .get<MicroAppDescriptor>(`/microapps/${this.microAppName}.json`)
        .toPromise();

      if (!descriptor) {
        throw new Error(`No descriptor for micro-app '${this.microAppName}'`);
      }

      const remote = await loadAndInitMicroApp(descriptor, this.sdk);

      if (!remote.mount) {
        throw new Error(`Micro-app '${this.microAppName}' does not export a mount() function`);
      }

      // For Angular, mount() will bootstrap the app itself (see init.ts)
      await remote.mount();

      // If you wanted to mount a component directly:
      // const compType = await remote.getRootComponent();
      // this.vc.clear();
      // this.vc.createComponent(compType);

    } catch (err) {
      console.error(err);
      this.vc.clear();
    }
  }
}
```
