export class SubBuilderFromLoggedUser {
  constructor(private authService: AuthService){}

  build(): Sub {
    var loginName = this.authService.getLoginName();
    var roles = this.authService.getRoles();
    var departments = this.authService.getDepartments();
    var mainDepartment = this.authService.getMainDepartment();

    var sub = new Sub()
      .setKind(loginName, SubjectTypes.User)
      .addAttr("mainDeptId", mainDepartment)

    roles.forEach(r => sub.addRole(r))
    departments.forEach(d => sub.addDepartment(d))

    return sub;
  }
}

```

