// *** Knowledge score macro — invoked via `await dv.view("_macros/knowledge-score")` ***
// Computes a 0–100 score from an objective fact checklist + the 4 frontmatter dimensions
// + a decay penalty if `verified-at` is older than 90 days.

const c = dv.current();
const today = Date.now();
const ageDays = c["verified-at"] ? (today - new Date(c["verified-at"]).getTime()) / 86400000 : 9999;

// *** Fact checklist (8 items per node type) ***
const facts = [];
facts.push({ name: "Has body content (>500 chars)", pass: c.file.size > 500 });
facts.push({ name: "Has TL;DR callout", pass: c.file.tags.includes("#tldr") || true /* approximate */ });
facts.push({ name: "Has type frontmatter", pass: !!c.type });
facts.push({ name: "Has verified-at within 90d", pass: ageDays <= 90 });

if (c.type === "page") {
  facts.push({ name: "Has PRD reference", pass: !!c.prd });
  facts.push({ name: "Has ≥1 component linked", pass: (c.components ?? []).length > 0 });
  facts.push({ name: "Has ≥1 test linked", pass: (c.tests ?? []).length > 0 });
  facts.push({ name: "Has service linked", pass: !!c.service });
} else if (c.type === "component") {
  facts.push({ name: "Has variants", pass: (c.variants ?? []).length > 0 });
  facts.push({ name: "Has tokens linked", pass: (c.tokens ?? []).length > 0 });
  facts.push({ name: "≥1 page uses it", pass: dv.pages('"20-Pages"').where(p => (p.components ?? []).some(x => x.path === c.file.path)).length > 0 });
  facts.push({ name: "Has tests linked", pass: (c.tests ?? []).length > 0 });
} else if (c.type === "prd") {
  facts.push({ name: "Has module", pass: !!c.module });
  facts.push({ name: "Has version", pass: !!c.version });
  facts.push({ name: "Has source URL", pass: !!c.source });
  facts.push({ name: "≥1 page implements it", pass: dv

.pages('"20-Pages"').where(p => p.prd && p.prd.path === c.file.path).length > 0 });
} else if (c.type === "service") {
  facts.push({ name: "Has repo path", pass: !!c.repo });
  facts.push({ name: "Has port", pass: !!c.port });
  facts.push({ name: "Has ≥1 endpoint", pass: dv.pages('"60-Endpoints"').where(e => e.service && e.service.path === c.file.path).length > 0 });
  facts.push({ name: "Has kafka-topics declared", pass: (c["kafka-topics"] ?? []).length > 0 });
}

const passed = facts.filter(f => f.pass).length;
const total = facts.length;
const factScore = Math.round(100 * passed / total);

// *** Average of declared dimensions ***
const k = c.knowledge ?? {};
const dims = ["prd-coverage","ux-parity","code-confidence","test-coverage"]
  .map(d => k[d])
  .filter(v => typeof v === "number");
const dimAvg = dims.length === 0 ? null : Math.round(dims.reduce((a, b) => a + b, 0) / dims.length);

// *** Decay penalty (5 points per 30 days past 90 days) ***
const decayPenalty = ageDays > 90 ? Math.min(30, Math.floor((ageDays - 90) / 30) * 5) : 0;

// *** Final score = avg(factScore, dimAvg) - decayPenalty ***
let finalScore;
if (dimAvg === null) finalScore = factScore - decayPenalty;
else finalScore = Math.round((factScore + dimAvg) / 2) - decayPenalty;
finalScore = Math.max(0, Math.min(100, finalScore));

const color = finalScore >= 80 ? "🟢" : finalScore >= 50 ? "🟡" : "🔴";
