// *** Transitive footprint macro ***
// Invoked via `await dv.view("_macros/transitive-footprint")`.
// Walks every outbound typed relation (components, tokens, endpoints, tests, gaps,
// questions, service, prd) up to `MAX_DEPTH` and renders a tree + flat table.
//
// Use this when the default Local Graph view (depth=1) hides the chain you care about,
// e.g. Page -> Component -> Token.

const MAX_DEPTH = 3;
const RELATION_FIELDS = [
  "prd", "service", "page", "component", "components", "tokens",
  "endpoints", "tests", "gaps", "questions", "prd-reference"
];

const start = dv.current();
const visited = new Map();        // path -> { node, depth }
const edges = [];                 // [from, to, field]

function neighborsOf(node) {
  const out = [];
  for (const f of RELATION_FIELDS) {
    const v = node[f];
    if (!v) continue;
    const arr = Array.isArray(v) ? v : [v];
    for (const link of arr) {
      if (link?.path) out.push({ field: f, link });
    }
  }
  return out;
}

function walk(node, depth) {
  if (depth > MAX_DEPTH) return;
  for (const { field, link } of neighborsOf(node)) {
    const target = dv.page(link.path);
    edges.push([node.file.path, link.path, field]);
    if (!target) continue;
    if (visited.has(link.path)) continue;
    visited.set(link.path, { node: target, depth });
    walk(target, depth + 1);
  }
}

visited.set(start.file.path, { node: start, depth: 0 });
walk(start, 1);

// *** Group nodes by type and depth ***
const byType = {};
for (const [, entry] of visited) {
  const t = entry.node.type ?? "(untyped)";
  byType[t] = byType[t] ?? [];
  byType[t].push(entry);
}

dv.header(3, `Transitive footprint (depth ≤ ${MAX_DEPTH})`);
dv.paragraph(`**${visited.size - 1}** unique reachable notes via **${edges.length}** typed e

dges.`);

dv.header(4, "Reachable by type");
for (const [t, entries] of Object.entries(byType).sort()) {
  dv.table(
    ["Note", "Depth"],
    entries
      .filter(e => e.node.file.path !== start.file.path)
      .sort((a, b) => a.depth - b.depth)
      .map(e => [e.node.file.link, e.depth])
  );
  dv.paragraph(`**${t}**: ${entries.length}`);
}

dv.header(4, "Edge list");
dv.table(
  ["From", "Field", "To"],
  edges.map(([f, t, fld]) => [dv.fileLink(f), fld, dv.fileLink(t)])
);
